function needsRehash(stored, want) {
  // Write your solution here
  var m = /m=(\d+),t=(\d+),p=(\d+)/.exec(stored);
  if (!m) return true;
  return Number(m[1]) < want.m || Number(m[2]) < want.t || Number(m[3]) < want.p;
}

